-- LOCAL disposable DB only. All fixture changes roll back.
\set ON_ERROR_STOP on
begin;
create function pg_temp.assert_true(ok boolean,msg text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'ASSERT: %',msg; end if; end $$;
create function pg_temp.expect_error(statement text,code text) returns void language plpgsql as $$ begin begin execute statement; exception when others then if sqlstate=code then return; else raise; end if; end; raise exception 'Expected SQLSTATE %',code; end $$;
insert into auth.users values('46a2400a-f04f-4b78-bd20-e3f75507b154'),('a4e1906d-b915-4e00-9b4e-657beeb396ae'),('00000000-0000-4000-8000-000000000003');
insert into public.user_profiles values('46a2400a-f04f-4b78-bd20-e3f75507b154','admin','owner1@example.com','관리자1'),('a4e1906d-b915-4e00-9b4e-657beeb396ae','user','owner2@example.com','관리자2'),('00000000-0000-4000-8000-000000000003','user','outside@example.com','미지정');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
select pg_temp.expect_error($q$select marketing_find_organizations('한빛')$q$,'42501');
select pg_temp.expect_error($q$select marketing_create_organization('10000000-0000-4000-8000-000000000001','한빛','IT기업','{}','등록 근거')$q$,'42501');
select set_config('request.jwt.claim.sub','a4e1906d-b915-4e00-9b4e-657beeb396ae',true);
select marketing_create_organization('10000000-0000-4000-8000-000000000001','한빛','IT기업',array['HANBIT'],'회사 홈페이지 확인','confirmed');
select marketing_create_organization('10000000-0000-4000-8000-000000000001','한빛','IT기업',array['HANBIT'],'회사 홈페이지 확인','confirmed');
select pg_temp.assert_true((select count(*)=1 from marketing_organizations),'create is idempotent');
select pg_temp.assert_true((select count(*)=1 from marketing_review_events where action='회사·기관 등록'),'one audit event for retry');
select pg_temp.assert_true((select count(*)=0 from marketing_contacts),'registering company does not register a Contact');
select pg_temp.assert_true(marketing_find_organizations('hanbit')->'rows'->0->>'name'='한빛','approved alias search');
select pg_temp.assert_true(marketing_find_organizations('(주) 한빛')->'rows'->0->>'name'='한빛','legal designator variant is searched but not merged');
select pg_temp.assert_true((marketing_find_organizations('%')->>'total')::integer=0,'search wildcard treated literally');
select pg_temp.assert_true((marketing_find_organizations('',1,'10000000-0000-4000-8000-000000000001')->>'total')::integer=1,'initial linked organization resolved by ID');
select pg_temp.expect_error($q$select marketing_create_organization('10000000-0000-4000-8000-000000000002','(주)한빛','IT기업','{}','추가 등록')$q$,'23505');
select pg_temp.expect_error($q$select marketing_create_organization('10000000-0000-4000-8000-000000000002','다른회사','IT기업',array['HANBIT'],'추가 등록')$q$,'23505');
select pg_temp.expect_error($q$select marketing_create_organization('10000000-0000-4000-8000-000000000002','한빛','확인 필요','{}','추가 등록','confirmed',true)$q$,'22023');
select marketing_create_organization('10000000-0000-4000-8000-000000000002','한빛','IT기업','{}','별도 법인 등록 근거','pending',true);
select pg_temp.assert_true((marketing_find_organizations('한빛')->>'total')::integer=2,'separate legal entities remain distinct');
select pg_temp.expect_error($q$select marketing_create_organization('10000000-0000-4000-8000-000000000001','변조','IT기업','{}','다른 요청')$q$,'40001');
select pg_temp.expect_error($q$select marketing_submit('[{"requestKey":"20000000-0000-4000-8000-000000000001","requireOrganization":true,"data":{"company":"없는회사"}}]')$q$,'22023');
select pg_temp.expect_error($q$select marketing_submit('[{"requestKey":"20000000-0000-4000-8000-000000000001","requireOrganization":true,"organizationId":"10000000-0000-4000-8000-000000000009","data":{}}]')$q$,'22023');
select pg_temp.expect_error($q$select marketing_submit('[{"requestKey":"20000000-0000-4000-8000-000000000001","requireOrganization":true,"organizationId":"10000000-0000-4000-8000-000000000001","organizationVersion":2,"data":{}}]')$q$,'40001');
select marketing_submit('[{"requestKey":"20000000-0000-4000-8000-000000000001","requireOrganization":true,"organizationId":"10000000-0000-4000-8000-000000000001","organizationVersion":1,"data":{"company":"잘못된 회사명","name":"김서연","email":"test@example.com","source":"명함"},"source":{"companySelection":{"id":"위조"}}}]');
select set_config('test.submission',(select id::text from marketing_submissions where request_key='20000000-0000-4000-8000-000000000001'),true);
select pg_temp.assert_true((select submitted_organization_id='10000000-0000-4000-8000-000000000001' and data->>'company'='한빛' and source->'companySelection'->>'id'='10000000-0000-4000-8000-000000000001' from marketing_submissions where id=current_setting('test.submission')::uuid),'ID canonical company and DB-owned snapshot saved');
select pg_temp.expect_error($q$select marketing_submit('[{"requestKey":"20000000-0000-4000-8000-000000000001","requireOrganization":true,"organizationId":"10000000-0000-4000-8000-000000000002","organizationVersion":1,"data":{"company":"한빛","name":"김서연","email":"test@example.com","source":"명함"}}]')$q$,'22023');
select set_config('test.final',(select (data||jsonb_build_object('category','IT기업'))::text from marketing_submissions where id=current_setting('test.submission')::uuid),true);
select set_config('test.check',marketing_review_check(current_setting('test.submission')::uuid,current_setting('test.final')::jsonb,null,null)::text,true);
select pg_temp.assert_true(current_setting('test.check')::jsonb->'blockingErrors' ? '회사·기관에 먼저 등록한 뒤 검색 결과에서 선택해 주세요.','no inline organization creation at approval');
select pg_temp.expect_error(format('select marketing_review(%L,1,%L,%L,null,null,null,null,%L,%L,%L)',current_setting('test.submission'),'approve',current_setting('test.final'),'IT기업','승인 근거',jsonb_build_object('token',current_setting('test.check')::jsonb->>'token','reason','확인 완료')),'22023');
select pg_temp.assert_true(exists(select 1 from jsonb_array_elements(marketing_review_check(current_setting('test.submission')::uuid,current_setting('test.final')::jsonb,null,'10000000-0000-4000-8000-000000000002')->'conflicts') x where x->>'key'='submitted-company'),'same-name different ID change requires evidence');
select set_config('test.check',marketing_review_check(current_setting('test.submission')::uuid,current_setting('test.final')::jsonb,null,'10000000-0000-4000-8000-000000000001')::text,true);
select pg_temp.assert_true(jsonb_array_length(current_setting('test.check')::jsonb->'blockingErrors')=0,'registered organization can pass final check');
select marketing_review(current_setting('test.submission')::uuid,1,'approve',current_setting('test.final')::jsonb,null,null,'10000000-0000-4000-8000-000000000001',1,'IT기업','동일 법인·명함·정제 자료 확인',jsonb_build_object('token',current_setting('test.check')::jsonb->>'token','reason','확인 자료 근거'));
select pg_temp.assert_true((select count(*)=1 from marketing_contacts where organization_id='10000000-0000-4000-8000-000000000001'),'approval links chosen ID');
select pg_temp.assert_true((select count(*)=2 from marketing_organizations),'approval never creates organization');
-- Existing spreadsheet submissions remain collectible and can still be rejected without a company.
select marketing_submit('[{"requestKey":"20000000-0000-4000-8000-000000000002","data":{}}]');
select marketing_review((select id from marketing_submissions where request_key='20000000-0000-4000-8000-000000000002'),1,'reject','{}',null,null,null,null,'확인 필요','회사 등록 후 다시 제출',null);
reset role;
create function pg_temp.reject_org_audit() returns trigger language plpgsql as $$ begin raise exception 'audit failure' using errcode='P0001'; end $$;
create trigger test_org_audit before insert on marketing_review_events for each row execute function pg_temp.reject_org_audit();
set local role authenticated;
select pg_temp.expect_error($q$select marketing_create_organization('10000000-0000-4000-8000-000000000003','새법인','IT기업','{}','등록 근거')$q$,'P0001');
select pg_temp.assert_true(not exists(select 1 from marketing_organizations where id='10000000-0000-4000-8000-000000000003'),'audit failure rolls back creation');
rollback;
